class Solution:
    def shortestCommonSupersequence(self, str1: str, str2: str) -> str:
        m, n = len(str1), len(str2)

        # Create DP table to store lengths of LCS
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        # Fill the DP table
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if str1[i - 1] == str2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        # Reconstruct the shortest common supersequence from DP table
        result = []
        i, j = m, n

        while i > 0 and j > 0:
            if str1[i - 1] == str2[j - 1']:
                # Character is part of LCS, add once
                result.append(str1[i - 1])
                i -= 1
                j -= 1
            elif dp[i - 1][j] >= dp[i][j - 1]:
                # Move up, add character from str1
                result.append(str1[i - 1])
                i -=
            else:
                # Move left, add character from str2
                result.append(str2[j - 1])
                j -= 1

        # Add remaining characters from str1
        while i > 0:
            result.append(str1[i - 1])
            i -= 1

        # Add remaining characters from str2
        while j > 0:
            result.append(str2[j - 1])
            j -= 1

        # Reverse to get correct order
        return ''.join(reversed(result))
